{"tokens": ["En", "el", "año", "2023", "suceden", "tres", "cosas", "importantes", "para", "la", "Cooperación", "Española", ".", "1", ".", "Aprobación", "de", "una", "nueva", "ley", ":", "En", "febrero", "se", "aprobó", "la", "Ley", "1/2023", "de", "Cooperación", "para", "el", "Desarrollo", "Sostenible", "y", "la", "Solidaridad", "Global", ",", "después", "de", "dialogar", "con", "todos", "los", "implicados", "y", "obtener", "un", "gran", "apoyo", "en", "el", "parlamento", ".", "Esta", "ley", "establece", "un", "objetivo", "nuevo", ":", "destinar", "el", "0,7%", "de", "nuestra", "riqueza", "nacional", "a", "la", "ayuda", "para", "el", "desarrollo", "hasta", "el", "año", "2030", ".", "También", ",", "crea", "un", "nuevo", "modelo", "de", "cooperación", ",", "organiza", "el", "sistema", "según", "las", "fortalezas", "de", "cada", "uno", "y", "mejora", "sus", "órganos", "de", "gobierno", ".", "2", ".", "Inicio", "de", "un", "proyecto", "ambicioso", ":", "Esta", "ley", "marca", "el", "comienzo", "de", "un", "proyecto", "grande", "para", "reformar", "el", "sistema", "de", "cooperación", ".", "Ya", "se", "están", "dando", "los", "primeros", "pasos", "en", "este", "proceso", "y", "seguirá", "avanzando", "durante", "el", "resto", "del", "año", "2023", "."], "oraciones": ["En el año 2023 suceden tres cosas importantes para la Cooperación Española. 

", "1.", "Aprobación de una nueva ley: En febrero se aprobó la Ley 1/2023 de Cooperación para el Desarrollo Sostenible y la Solidaridad Global, después de dialogar con todos los implicados y obtener un gran apoyo en el parlamento.", "Esta ley establece un objetivo nuevo: destinar el 0,7% de nuestra riqueza nacional a la ayuda para el desarrollo hasta el año 2030.", "También, crea un nuevo modelo de cooperación, organiza el sistema según las fortalezas de cada uno y mejora sus órganos de gobierno.

", "2.", "Inicio de un proyecto ambicioso: Esta ley marca el comienzo de un proyecto grande para reformar el sistema de cooperación.", "Ya se están dando los primeros pasos en este proceso y seguirá avanzando durante el resto del año 2023."], "lemas": ["en", "el", "año", "2023", "suceder", "tres", "cosa", "importante", "para", "el", "Cooperación", "Española", ".", "1", ".", "aprobación", "de", "uno", "nuevo", "ley", ":", "En", "febrero", "él", "aprobar", "el", "Ley", "1/2023", "de", "Cooperación", "para", "el", "Desarrollo", "Sostenible", "y", "el", "Solidaridad", "Global", ",", "después", "de", "dialogar", "con", "todo", "el", "implicado", "y", "obtener", "uno", "gran", "apoyo", "en", "el", "parlamento", ".", "este", "ley", "establecer", "uno", "objetivo", "nuevo", ":", "destinar", "el", "0,7%", "de", "nuestro", "riqueza", "nacional", "a", "el", "ayuda", "para", "el", "desarrollo", "hasta", "el", "año", "2030", ".", "también", ",", "creer", "uno", "nuevo", "modelo", "de", "cooperación", ",", "organizar", "el", "sistema", "según", "el", "fortaleza", "de", "cada", "uno", "y", "mejorar", "su", "órgano", "de", "gobierno", ".", "2", ".", "inicio", "de", "uno", "proyecto", "ambicioso", ":", "este", "ley", "marcar", "el", "comienzo", "de", "uno", "proyecto", "grande", "para", "reformar", "el", "sistema", "de", "cooperación", ".", "ya", "él", "estar", "dar", "el", "primero", "paso", "en", "este", "proceso", "y", "seguir", "avanzar", "durante", "el", "resto", "del", "año", "2023", "."], "pos": ["ADP", "DET", "NOUN", "NUM", "VERB", "NUM", "NOUN", "ADJ", "ADP", "DET", "PROPN", "PROPN", "PUNCT", "NUM", "PUNCT", "NOUN", "ADP", "DET", "ADJ", "NOUN", "PUNCT", "ADP", "NOUN", "PRON", "VERB", "DET", "PROPN", "NUM", "ADP", "PROPN", "ADP", "DET", "PROPN", "PROPN", "CCONJ", "DET", "PROPN", "PROPN", "PUNCT", "ADV", "ADP", "VERB", "ADP", "DET", "DET", "ADJ", "CCONJ", "VERB", "DET", "ADJ", "NOUN", "ADP", "DET", "PROPN", "PUNCT", "DET", "NOUN", "VERB", "DET", "NOUN", "ADJ", "PUNCT", "VERB"